// `bunnytrail init [dir]` — scaffolds a new world repo: thin
// SvelteKit shell + content/content_meta/assets scaffolding directories
// (empty — the user brings their own world). Does NOT install
// dependencies; the user runs `npm install` themselves after.
//
// Layout produced:
//   <dir>/
//     .gitignore
//     .env.example
//     README.md
//     package.json
//     svelte.config.js
//     tsconfig.json
//     vite.config.ts
//     src/
//       app.d.ts
//       app.html
//       hooks.server.ts
//       routes/                  (generated by ./shims.ts, consumer mode)
//     assets/
//       inline-svg.css
//       README.md
//     content/                   (empty — your worldbuilding lives here)
//     content_meta/
//       kinds/                   (empty — declare taxonomies here)
import { copyFile, mkdir, readFile, writeFile } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { generateShims } from './shims';

const HERE = dirname(fileURLToPath(import.meta.url));
const TEMPLATES = resolve(HERE, 'templates');

interface FileCopy {
	from: string;
	to: string;
}

// Static (verbatim) copies. Dotfile sources are stored without the
// leading dot because npm strips dotfiles from `files:` arrays.
// `.tpl` suffix on template-source filenames keeps SvelteKit, Vite,
// and TS from scanning the templates dir as live project files.
// Stripped when copied.
const STATIC: FileCopy[] = [
	{ from: 'gitignore', to: '.gitignore' },
	{ from: 'env.example', to: '.env.example' },
	{ from: 'svelte.config.js.tpl', to: 'svelte.config.js' },
	{ from: 'tsconfig.json.tpl', to: 'tsconfig.json' },
	{ from: 'vite.config.ts.tpl', to: 'vite.config.ts' },
	{ from: 'src/app.html.tpl', to: 'src/app.html' },
	{ from: 'src/app.d.ts.tpl', to: 'src/app.d.ts' },
	{ from: 'src/hooks.server.ts.tpl', to: 'src/hooks.server.ts' },
	{ from: 'inline-svg.css', to: 'assets/inline-svg.css' },
	{ from: 'assets-README.md', to: 'assets/README.md' }
];

// Templated copies — read source, substitute __NAME__, write to dest.
const TEMPLATED: FileCopy[] = [
	{ from: 'package.json.tpl', to: 'package.json' },
	{ from: 'README.md.tpl', to: 'README.md' }
];

// Empty directories the user is meant to fill in.
const EMPTY_DIRS = ['content', 'content_meta/kinds'];

export async function init(argv: string[]): Promise<number> {
	const target = resolve(argv[0] ?? '.');
	const name = target.split('/').filter(Boolean).pop() ?? 'my-world';

	console.log(`bunnytrail init → ${target}`);
	await mkdir(target, { recursive: true });

	// Refuse to overwrite an existing package.json. Empty dirs are fine.
	if (existsSync(resolve(target, 'package.json'))) {
		console.error(`error: ${target}/package.json already exists; aborting`);
		return 1;
	}

	const skipped: string[] = [];
	const wrote: string[] = [];

	for (const { from, to } of STATIC) {
		const dest = resolve(target, to);
		if (existsSync(dest)) {
			skipped.push(to);
			continue;
		}
		await mkdir(dirname(dest), { recursive: true });
		await copyFile(resolve(TEMPLATES, from), dest);
		wrote.push(to);
	}

	for (const { from, to } of TEMPLATED) {
		const dest = resolve(target, to);
		if (existsSync(dest)) {
			skipped.push(to);
			continue;
		}
		const src = await readFile(resolve(TEMPLATES, from), 'utf8');
		await mkdir(dirname(dest), { recursive: true });
		await writeFile(dest, src.replaceAll('__NAME__', name));
		wrote.push(to);
	}

	for (const dir of EMPTY_DIRS) {
		await mkdir(resolve(target, dir), { recursive: true });
	}

	// Shims are generated artifacts — always overwrite.
	const shims = await generateShims({ targetDir: target, mode: 'consumer' });
	console.log(`  wrote ${wrote.length} files, ${shims.length} shims`);
	if (skipped.length > 0) {
		console.log(`  skipped (already exists): ${skipped.join(', ')}`);
	}

	console.log(`
Done.

Next steps:
  cd ${argv[0] ?? '.'}
  npm install
  cp .env.example .env       # optional — defaults to ./
  # drop your content into content/ and content_meta/kinds/
  npm run dev
`);
	return 0;
}
